<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { addGroupMember, configureGroupWikiRoot, createGroupRole, deleteGroupRole, getCollabGroup, getGroupRequirements, getGroupTemplatePreview, publishCollabGroup, removeGroupMember, replaceGroupRoleMembers, updateGroupStageTemplate, type CollabGroup, type GroupRole, type RequirementSummary } from '../api/collab-groups.api'
import { COLLAB_STAGES, searchCollabUsers, type CollabStage, type CollabUser } from '../api/collab-projects.api'
import CollabRequirementWorkflow from './CollabRequirementWorkflow.vue'
import { useAuthStore } from '../stores/auth'

const route=useRoute();const router=useRouter();const auth=useAuthStore();const groupKey=computed(()=>String(route.params.groupKey))
const group=ref<CollabGroup|null>(null);const requirements=ref<RequirementSummary[]>([]);const loading=ref(true);const busy=ref(false);const error=ref('');const wikiUrl=ref('');const query=ref('');const hits=ref<CollabUser[]>([]);const newRoleName=ref('');const preview=ref<{valid:boolean;issues:{stageKey:string;duty?:string;message:string}[];warnings:{stageKey:string;duty?:string;message:string}[]}|null>(null)
type StageDraft={ownerRoleKey:string|null;reviewerRoleKeys:string[];included:boolean}
const stageDrafts=ref<Record<string,StageDraft>>({});const savedStageDrafts=ref<Record<string,StageDraft>>({});const savingStageKeys=ref<string[]>([]);const savingAllStages=ref(false)
const isOwner=computed(()=>group.value?.ownerUserId===auth.user?.id)
const members=computed(()=>group.value?.members||[]);const roles=computed(()=>group.value?.roles||[]);const stages=computed(()=>[...(group.value?.stages||[])].sort((a,b)=>(a.order||a.stageOrder||COLLAB_STAGES.findIndex(s=>s.key===a.stageKey)+1)-(b.order||b.stageOrder||COLLAB_STAGES.findIndex(s=>s.key===b.stageKey)+1)))
const templateStages=computed<CollabStage[]>(()=>stages.value.map((stage,index)=>({stageId:index+1,stageKey:stage.stageKey,title:stage.title,stageOrder:stage.order||stage.stageOrder||index+1,status:stage.included?'WAITING':'SKIPPED',ownerUserId:0,attemptNo:1,versionNo:stage.versionNo||0,ownerRoleName:roles.value.find(role=>role.roleKey===stage.ownerRoleKey)?.roleName||stage.ownerRoleName,reviewerRoleNames:(stage.reviewerRoleKeys||[]).map(key=>roles.value.find(role=>role.roleKey===key)?.roleName||key),reviewerRoleName:(stage.reviewerRoleKeys||[]).map(key=>roles.value.find(role=>role.roleKey===key)?.roleName||key).join('、')})))
function focusStage(stageKey:string){document.getElementById(`template-${stageKey}`)?.scrollIntoView({behavior:'smooth',block:'center'})}
const canCreateRequirement=computed(()=>group.value?.status==='PUBLISHED'&&!!group.value.gitlabRootUrl)
const wikiRootLocked=computed(()=>group.value?.status==='PUBLISHED'&&!group.value.legacyImport)
function roleMemberIds(role:GroupRole){return role.userIds?.length?role.userIds:(role.members||[]).map(m=>m.userId)}
function stageDirty(stageKey:string){const draft=stageDrafts.value[stageKey],saved=savedStageDrafts.value[stageKey];if(!draft||!saved)return false;return (draft.ownerRoleKey||null)!==(saved.ownerRoleKey||null)||draft.included!==saved.included||[...draft.reviewerRoleKeys].sort().join('|')!==[...saved.reviewerRoleKeys].sort().join('|')}
const dirtyStageCount=computed(()=>stages.value.filter(stage=>stageDirty(stage.stageKey)).length)
function snapshotStage(stage:NonNullable<CollabGroup['stages']>[number]):StageDraft{return{ownerRoleKey:stage.ownerRoleKey||null,reviewerRoleKeys:[...(stage.reviewerRoleKeys||[])],included:stage.included}}
function msg(e:unknown){return(e as{response?:{data?:{message?:string;code?:string}}})?.response?.data?.message||(e as Error)?.message||'请求失败'}
async function load(){loading.value=true;error.value='';try{const [g,r]=await Promise.all([getCollabGroup(groupKey.value),getGroupRequirements(groupKey.value)]);for(const stage of g.stages||[])stage.reviewerRoleKeys=stage.reviewerRoleKeys??(stage.reviewerRoleKey?[stage.reviewerRoleKey]:[]);group.value=g;requirements.value=r;wikiUrl.value=g.wikiRootUrl||'';stageDrafts.value=Object.fromEntries((g.stages||[]).map(stage=>[stage.stageKey,snapshotStage(stage)]));savedStageDrafts.value=Object.fromEntries((g.stages||[]).map(stage=>[stage.stageKey,snapshotStage(stage)]))}catch(e){error.value=msg(e)}finally{loading.value=false}}
async function search(){if(!query.value.trim()){hits.value=[];return}try{hits.value=await searchCollabUsers(query.value.trim())}catch(e){error.value=msg(e)}}
async function addMember(u:CollabUser){busy.value=true;try{await addGroupMember(groupKey.value,u.id??u.userId);hits.value=[];query.value='';await load()}catch(e){error.value=msg(e)}finally{busy.value=false}}
async function removeMember(userId:number){busy.value=true;try{await removeGroupMember(groupKey.value,userId);await load()}catch(e){error.value=msg(e)}finally{busy.value=false}}
async function addRole(){const n=newRoleName.value.trim();if(!n)return;busy.value=true;try{const role=await createGroupRole(groupKey.value,n);if(group.value){group.value.roles=[...(group.value.roles||[]),role];group.value.templateVersion+=1}newRoleName.value=''}catch(e){window.alert(`新增角色失败：${msg(e)}`)}finally{busy.value=false}}
async function removeRole(role:GroupRole){if(!window.confirm(`删除角色“${role.roleName||role.name}”？`))return;busy.value=true;try{await deleteGroupRole(groupKey.value,role.roleKey);if(group.value){group.value.roles=(group.value.roles||[]).filter(item=>item.roleKey!==role.roleKey);group.value.templateVersion+=1}}catch(e){window.alert(`删除角色失败：${msg(e)}`)}finally{busy.value=false}}
async function toggleRoleMember(role:GroupRole,userId:number){const ids=new Set(roleMemberIds(role));ids.has(userId)?ids.delete(userId):ids.add(userId);busy.value=true;try{const updated=await replaceGroupRoleMembers(groupKey.value,role.roleKey,[...ids]);if(group.value){group.value.roles=(group.value.roles||[]).map(item=>item.roleKey===role.roleKey?updated:item);group.value.templateVersion+=1}}catch(e){window.alert(`更新角色成员失败：${msg(e)}`)}finally{busy.value=false}}
async function saveStage(stageKey:string):Promise<boolean>{const draft=stageDrafts.value[stageKey];if(!draft||!stageDirty(stageKey)||!group.value)return false;savingStageKeys.value=[...savingStageKeys.value,stageKey];try{const saved=await updateGroupStageTemplate(groupKey.value,stageKey,{ownerRoleKey:draft.ownerRoleKey||null,reviewerRoleKeys:[...draft.reviewerRoleKeys],included:draft.included,expectedVersion:group.value.templateVersion||0});const normalized:StageDraft={ownerRoleKey:saved.ownerRoleKey||null,reviewerRoleKeys:[...(saved.reviewerRoleKeys||[])],included:saved.included};savedStageDrafts.value={...savedStageDrafts.value,[stageKey]:normalized};stageDrafts.value={...stageDrafts.value,[stageKey]:{...normalized,reviewerRoleKeys:[...normalized.reviewerRoleKeys]}};group.value.templateVersion+=1;const current=group.value.stages?.find(stage=>stage.stageKey===stageKey);if(current)Object.assign(current,normalized,{reviewerRoleKey:saved.reviewerRoleKey,reviewerRoleName:saved.reviewerRoleName,reviewerRoleNames:saved.reviewerRoleNames,versionNo:saved.versionNo});return true}catch(e){window.alert(`保存“${stages.value.find(stage=>stage.stageKey===stageKey)?.title||stageKey}”失败：${msg(e)}`);return false}finally{savingStageKeys.value=savingStageKeys.value.filter(key=>key!==stageKey)}}
async function saveAllStages(){if(savingAllStages.value)return;savingAllStages.value=true;try{for(const stage of stages.value)if(stageDirty(stage.stageKey)&&!(await saveStage(stage.stageKey)))break}finally{savingAllStages.value=false}}
async function checkTemplate(){busy.value=true;try{preview.value=await getGroupTemplatePreview(groupKey.value)}catch(e){error.value=msg(e)}finally{busy.value=false}}
async function publish(){busy.value=true;error.value='';try{preview.value=await getGroupTemplatePreview(groupKey.value);if(!preview.value.valid){error.value='推送前配置检查未通过，请查看下方问题清单';return}group.value=await publishCollabGroup(groupKey.value,group.value?.versionNo||0);await load()}catch(e){error.value=msg(e)}finally{busy.value=false}}
async function saveWiki(){if(!wikiUrl.value.trim())return;busy.value=true;try{await configureGroupWikiRoot(groupKey.value,wikiUrl.value.trim());wikiUrl.value='';await load()}catch(e){error.value=msg(e)}finally{busy.value=false}}
onMounted(load)
</script>

<template><main class="page"><button class="back" @click="router.push({name:'collab-projects'})">← 项目组</button><div v-if="error" class="error">{{error}} <button @click="error=''">关闭</button></div><div v-if="loading" class="empty">正在加载项目组…</div><template v-else-if="group">
  <header class="hero"><div><span class="eyebrow">GROUP / {{group.homeTeamName||'COLLAB'}}</span><h1>{{group.name}}</h1><p>{{group.description||'项目组配置与需求协作空间'}}</p></div><div class="hero-actions"><span class="state" :class="group.status.toLowerCase()">{{group.status==='DRAFT'?'草稿':group.status==='PUBLISHED'?'已推送':'已归档'}}</span><button v-if="isOwner&&group.status==='DRAFT'" class="primary" :disabled="busy" @click="publish">{{busy?'检查中…':'推送项目组'}}</button><button v-if="group.status==='PUBLISHED'" class="primary" @click="router.push({name:'collab-requirement-create',params:{groupKey}})">＋ 新建需求</button></div></header>
  <section class="summary"><div><small>归属团队</small><b>{{group.homeTeamName||group.homeTeamId}}</b></div><div><small>GitLab 根目录</small><a :href="group.gitlabRootUrl" target="_blank" rel="noopener">{{group.gitlabRootUrl}}</a></div><div><small>模板版本</small><b>v{{group.templateVersion}}</b></div><div><small>需求</small><b>{{requirements.length}} 条</b></div></section>
  <section class="panel"><header><div><h2>项目组成员</h2><p>已推送后，成员可查看项目组及其需求。</p></div><span>{{members.length}} 人</span></header><div class="member-list"><div v-for="m in members" :key="m.userId" class="member"><span class="avatar">{{m.displayName?.slice(0,1)||'?'}}</span><span>{{m.displayName}}<small>{{m.username}}</small></span><b>{{m.memberType==='OWNER'?'Owner':'成员'}}</b><button v-if="isOwner&&m.memberType!=='OWNER'&&m.userId!==group.ownerUserId" :disabled="busy" @click="removeMember(m.userId)">移除</button></div></div><div v-if="isOwner" class="add-row"><input v-model="query" placeholder="按姓名或账号搜索成员" @keydown.enter.prevent="search"><button class="secondary" @click="search">搜索</button></div><div v-if="hits.length" class="hits"><button v-for="u in hits" :key="u.id??u.userId" @click="addMember(u)">＋ {{u.displayName}} <small>{{u.username}}</small></button></div></section>
  <section class="panel"><header><div><h2>自定义角色</h2><p>角色创建后名称固定；可以调整成员，或删除不再需要的角色。</p></div><span>{{roles.length}} 个角色</span></header><div class="role-list"><article v-for="role in roles" :key="role.roleKey" class="role-card"><div class="role-head"><strong>{{role.roleName||role.name}}</strong><button v-if="isOwner" class="danger" :disabled="busy||group.status==='ARCHIVED'" @click="removeRole(role)">删除</button><span>{{roleMemberIds(role).length}} 人</span></div><div class="role-members"><label v-for="m in members" :key="m.userId"><input type="checkbox" :checked="roleMemberIds(role).includes(m.userId)" :disabled="!isOwner||busy||group.status==='ARCHIVED'" @change="toggleRoleMember(role,m.userId)">{{m.displayName}}</label></div></article><div v-if="!roles.length" class="empty small">尚未创建自定义角色。</div></div><div v-if="isOwner&&group.status!=='ARCHIVED'" class="add-row"><input v-model="newRoleName" maxlength="100" placeholder="输入新角色名称"><button class="primary" :disabled="busy||!newRoleName.trim()" @click="addRole">新增角色</button></div></section>
  <CollabRequirementWorkflow :stages="templateStages" mode="template" @open-stage="focusStage" />
  <section class="panel workflow"><header><div><h2>阶段角色配置</h2><p>流程节点只显示角色名称；变更模板仅影响之后创建的需求。</p></div><div class="stage-save-actions"><span>模板 v{{group.templateVersion}}</span><button v-if="isOwner" class="primary" :disabled="savingAllStages||savingStageKeys.length>0||dirtyStageCount===0" @click="saveAllStages">{{savingAllStages?'正在保存…':`全部保存${dirtyStageCount?`（${dirtyStageCount}）`:''}`}}</button></div></header><div class="stages"><article v-for="stage in stages" :id="`template-${stage.stageKey}`" :key="stage.stageKey" class="stage-row"><b>{{String(stage.order||stage.stageOrder||COLLAB_STAGES.findIndex(s=>s.key===stage.stageKey)+1).padStart(2,'0')}} {{stage.title||COLLAB_STAGES.find(s=>s.key===stage.stageKey)?.title||stage.stageKey}}</b><label><span>负责人角色</span><select v-model="stageDrafts[stage.stageKey].ownerRoleKey" :disabled="!isOwner||group.status==='ARCHIVED'||savingAllStages||savingStageKeys.length>0"><option :value="null">未配置</option><option v-for="r in roles" :key="r.roleKey" :value="r.roleKey">{{r.roleName||r.name}}</option></select></label><label><span>审批人角色</span><t-select v-model="stageDrafts[stage.stageKey].reviewerRoleKeys" multiple filterable clearable :disabled="!isOwner||group.status==='ARCHIVED'||savingAllStages||savingStageKeys.length>0" :options="roles.map(r=>({label:r.roleName||r.name||r.roleKey,value:r.roleKey}))" placeholder="选择审批角色，可多选" /></label><label class="included"><input v-model="stageDrafts[stage.stageKey].included" type="checkbox" :disabled="!isOwner||group.status==='ARCHIVED'||savingAllStages||savingStageKeys.length>0">默认纳入</label><button v-if="isOwner" class="secondary" :disabled="!stageDirty(stage.stageKey)||savingAllStages||savingStageKeys.length>0" @click="saveStage(stage.stageKey)">{{savingStageKeys.includes(stage.stageKey)?'保存中…':'保存'}}</button></article></div></section>
  <section class="panel"><header><div><h2>飞书 Wiki</h2><p>项目组目录作为组级共享根节点，需求会在其下建立独立目录。</p></div><span>{{group.feishuStatus||'尚未配置'}}</span></header><p v-if="group.wikiRootUrl">{{group.wikiRootUrl}}</p><p v-if="wikiRootLocked" class="muted">项目组推送后，Wiki 根节点已锁定。</p><div v-if="isOwner&&!wikiRootLocked" class="add-row"><input v-model="wikiUrl" placeholder="粘贴飞书 Wiki 根节点链接"><button class="secondary" :disabled="busy" @click="saveWiki">{{group.wikiRootUrl?'更新配置':'绑定 Wiki'}}</button></div></section>
  <section v-if="preview" class="panel checks"><h2>推送前检查</h2><p v-if="preview.valid" class="ok">配置完整，可以推送项目组。</p><ul v-else><li v-for="(issue,i) in preview.issues" :key="i"><b>{{issue.stageKey}}</b> · {{issue.message}}</li></ul><ul v-if="preview.warnings?.length"><li v-for="(warning,i) in preview.warnings" :key="`warning-${i}`"><b>提醒 · {{warning.stageKey}}</b> · {{warning.message}}</li></ul></section>
  <section class="panel"><header><div><h2>需求列表</h2><p>各需求拥有独立阶段、审批和产物。</p></div><button v-if="group.status==='PUBLISHED'" class="primary" :disabled="!canCreateRequirement" :title="!canCreateRequirement?'请先补充 GitLab 根目录':''" @click="router.push({name:'collab-requirement-create',params:{groupKey}})">＋ 新建需求</button></header><p v-if="group.status==='PUBLISHED'&&!canCreateRequirement" class="warning">此存量项目组尚未配置 GitLab 根目录，补齐后才能创建新需求。</p><div v-if="!requirements.length" class="empty small">项目组还没有需求。</div><div class="requirements"><button v-for="r in requirements" :key="r.requirementKey" class="requirement" @click="router.push({name:'collab-requirement-detail',params:{requirementKey:r.requirementKey}})"><strong>{{r.name}}</strong><span>{{r.approvalLevel}} · 模板 v{{r.inheritedTemplateVersion}} · {{r.status||'进行中'}}</span><b>打开 →</b></button></div></section>
  <footer v-if="isOwner&&group.status==='DRAFT'" class="publish-footer"><div><strong>草稿仅 Owner 可见</strong><p>推送后项目组成员可访问；模板仍可调整，新配置只用于后续新需求。</p></div><button class="secondary" :disabled="busy" @click="checkTemplate">预检配置</button><button class="primary" :disabled="busy" @click="publish">{{busy?'处理中…':'推送项目组'}}</button></footer>
</template></main></template>

<style scoped>
.page{max-width:1450px;margin:auto;padding:28px 32px 70px;color:var(--text-1)}.back{border:0;background:none;color:var(--text-2);padding:0 0 20px;cursor:pointer}.hero{display:flex;justify-content:space-between;align-items:flex-end;gap:24px;margin-bottom:20px}.eyebrow{font:700 10px var(--font-mono);letter-spacing:.15em;color:var(--accent-400)}h1{margin:7px 0;font-size:30px}.hero p{margin:0;color:var(--text-2)}.hero-actions{display:flex;align-items:center;gap:10px}.state{padding:7px 11px;border-radius:20px;background:var(--surface-3);font-size:12px}.state.draft{color:var(--warning)}.state.published{color:var(--success)}.primary,.secondary,.danger{border:0;border-radius:8px;padding:9px 13px;cursor:pointer;font-weight:650}.primary{background:var(--accent-600);color:white}.secondary{background:var(--surface-3);color:var(--text-1)}.danger{background:var(--error-soft);color:var(--error)}button:disabled{opacity:.5;cursor:not-allowed}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;padding:17px 20px;border:1px solid var(--border-1);border-radius:12px;background:var(--surface-1);margin-bottom:17px}.summary>div{display:grid;gap:6px;min-width:0}.summary small,.panel header p{color:var(--text-3);font-size:11px}.summary a{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--accent-400)}.panel{padding:18px 20px;margin-bottom:16px;border:1px solid var(--border-1);border-radius:12px;background:var(--surface-1)}.panel>header{display:flex;justify-content:space-between;align-items:center;margin-bottom:13px}.panel header h2{margin:0 0 5px;font-size:16px}.panel header p{margin:0;font-size:12px;color:var(--text-2)}.panel header>span{font-size:12px;color:var(--text-3)}.stage-save-actions{display:flex;align-items:center;gap:12px}.stage-save-actions>span{font-size:12px;color:var(--text-3)}.member-list{display:flex;flex-wrap:wrap;gap:9px}.member{display:flex;align-items:center;gap:8px;padding:7px 9px;border:1px solid var(--border-1);border-radius:9px}.avatar{display:grid;place-items:center;width:28px;height:28px;border-radius:50%;background:var(--surface-3)}.member>span:nth-child(2){font-size:12px}.member small{display:block;color:var(--text-3);font-size:10px}.member b,.member button{font-size:10px}.member button{border:0;background:none;color:var(--error);cursor:pointer}.add-row{display:flex;gap:8px;margin-top:12px}.add-row input,.role-head input,.stage-row select{min-width:0;box-sizing:border-box;padding:9px 10px;border:1px solid var(--border-2);border-radius:7px;background:var(--surface-2);color:var(--text-1)}.add-row input{flex:1}.hits{display:grid;max-height:160px;overflow:auto}.hits button{padding:8px;text-align:left;border:0;border-bottom:1px solid var(--border-1);background:transparent;color:var(--text-1);cursor:pointer}.hits small{margin-left:8px;color:var(--text-3)}.role-list{display:grid;gap:10px}.role-card{padding:12px;border:1px solid var(--border-1);border-radius:9px}.role-head{display:flex;align-items:center;gap:8px}.role-head input{flex:1}.role-head span{font-size:11px;color:var(--text-3)}.role-members{display:flex;flex-wrap:wrap;gap:9px 18px;margin-top:11px}.role-members label,.included{display:flex;align-items:center;gap:6px;font-size:12px;color:var(--text-2)}.stages{display:grid;gap:8px}.stage-row{display:grid;grid-template-columns:minmax(150px,1fr) minmax(180px,1fr) minmax(180px,1fr) 110px auto;align-items:center;gap:12px;padding:10px;border:1px solid var(--border-1);border-radius:9px}.stage-row>b{font-size:12px}.stage-row label{display:grid;gap:5px;font-size:10px;color:var(--text-3)}.stage-row select{width:100%}.stage-row .included{display:flex;white-space:nowrap}.requirements{display:grid}.requirement{display:grid;grid-template-columns:1fr auto auto;align-items:center;gap:20px;padding:12px 4px;border:0;border-top:1px solid var(--border-1);background:none;text-align:left;color:var(--text-1);cursor:pointer}.requirement span{font-size:11px;color:var(--text-3)}.requirement b{color:var(--accent-400);font-size:11px}.publish-footer{position:sticky;bottom:10px;display:flex;align-items:center;gap:9px;padding:15px 18px;border:1px solid var(--border-2);border-radius:12px;background:var(--surface-overlay-solid);box-shadow:var(--shadow-lg)}.publish-footer>div{flex:1}.publish-footer p{margin:4px 0 0;color:var(--text-3);font-size:12px}.checks ul{margin:8px 0;color:var(--error)}.ok{color:var(--success)}.empty{display:grid;place-items:center;min-height:120px;color:var(--text-3)}.empty.small{min-height:60px}.error{padding:10px;background:var(--error-soft);color:var(--error);margin:10px 0;border-radius:8px}.error button{float:right}@media(max-width:850px){.page{padding:22px 15px}.hero{align-items:flex-start;flex-direction:column}.summary{grid-template-columns:1fr 1fr}.stage-row{grid-template-columns:1fr 1fr}.stage-row>b{grid-column:1/-1}.stage-row .included{grid-column:1}.publish-footer{flex-wrap:wrap}.publish-footer>div{flex-basis:100%}.requirement{grid-template-columns:1fr auto}.requirement span{grid-row:2}.requirement b{grid-column:2;grid-row:1/3}}
</style>
